local H={}
function H.request(url,method,body,token)
 local ffi=require('ffi');ffi.cdef[[typedef void* HINTERNET; HINTERNET WinHttpOpen(const unsigned short*,unsigned long,const unsigned short*,const unsigned short*,unsigned long); HINTERNET WinHttpConnect(HINTERNET,const unsigned short*,unsigned short,unsigned long); HINTERNET WinHttpOpenRequest(HINTERNET,const unsigned short*,const unsigned short*,const unsigned short*,const unsigned short*,const unsigned short**,unsigned long); int WinHttpSendRequest(HINTERNET,const unsigned short*,unsigned long,void*,unsigned long,unsigned long,size_t); int WinHttpReceiveResponse(HINTERNET,void*); int WinHttpQueryHeaders(HINTERNET,unsigned long,const unsigned short*,void*,unsigned long*,unsigned long*); int WinHttpReadData(HINTERNET,void*,unsigned long,unsigned long*); int WinHttpCloseHandle(HINTERNET); int WinHttpSetOption(HINTERNET,unsigned long,void*,unsigned long); int WinHttpSetTimeouts(HINTERNET,int,int,int,int); int MultiByteToWideChar(unsigned int,unsigned long,const char*,int,unsigned short*,int);]]
 local win=ffi.load('winhttp');local kernel=ffi.load('kernel32');local function wide(s)local n=kernel.MultiByteToWideChar(65001,0,s,#s,nil,0);local b=ffi.new('unsigned short[?]',n+1);kernel.MultiByteToWideChar(65001,0,s,#s,b,n);return b end
 local scheme,host,port,path=url:match('^(https?)://([%w%.%-]+):?(%d*)(/?.*)$');assert(scheme,'Use an HTTP(S) address');assert(scheme=='https'or host=='127.0.0.1'or host=='localhost','Remote account servers require HTTPS');port=tonumber(port)or(scheme=='https'and 443 or 80);path=path==''and'/'or path
 local handles={};local function keep(h)assert(h~=nil,'Network connection failed');handles[#handles+1]=h;return h end
 local ok,result=xpcall(function()local session=keep(win.WinHttpOpen(wide('Stonegrove/0.3.61.0'),0,nil,nil,0));win.WinHttpSetTimeouts(session,10000,15000,15000,60000);local connection=keep(win.WinHttpConnect(session,wide(host),port,0));local request=keep(win.WinHttpOpenRequest(connection,wide(method or'GET'),wide(path),nil,nil,nil,scheme=='https'and 0x800000 or 0));local decompression=ffi.new('unsigned long[1]',1);win.WinHttpSetOption(request,118,decompression,4);local headers='Content-Type: application/json\r\n'..(token and('Authorization: Bearer '..token..'\r\n')or'');body=body or'';assert(win.WinHttpSendRequest(request,wide(headers),#headers,ffi.cast('void*',body),#body,#body,0)~=0,'Could not send request');assert(win.WinHttpReceiveResponse(request,nil)~=0,'Server unavailable or certificate invalid');local status=ffi.new('unsigned long[1]');local len=ffi.new('unsigned long[1]',4);assert(win.WinHttpQueryHeaders(request,19+0x20000000,nil,status,len,nil)~=0,'Missing HTTP status');local buf=ffi.new('char[65536]');local got=ffi.new('unsigned long[1]');local chunks,total={},0;repeat assert(win.WinHttpReadData(request,buf,65536,got)~=0,'Download failed');total=total+tonumber(got[0]);assert(total<=32000000,'Response too large');if got[0]>0 then chunks[#chunks+1]=ffi.string(buf,got[0])end until got[0]==0;return {status=tonumber(status[0]),body=table.concat(chunks)}end,debug.traceback)
 for i=#handles,1,-1 do win.WinHttpCloseHandle(handles[i])end;if not ok then error(result)end;return result
end
return H
